function initSea(){
  var sea=document.getElementById('sea'), box=document.getElementById('marks'), beam=document.getElementById('beamRot');
  if(!sea||!box||box.childNodes.length) return;
  var SPAN=78, els=[];
  RISKS.forEach(function(r,i){
    var a=-SPAN+(2*SPAN)*(i/(RISKS.length-1));
    var el=document.createElement('div'); el.className='mk'; el.dataset.a=a;
    el.innerHTML='<svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">'+r.i+'</svg><span>'+r.t+'</span>';
    box.appendChild(el); els.push(el);
  });
  function place(){
    var W=sea.clientWidth,H=sea.clientHeight,cx=W/2,cy=H-115;
    if(!W||!H) return;   /* блок ещё не отрисован: размеры появятся позже, тогда и расставим подписи */
    var rx=Math.max(110,W/2-215), ry=Math.max(80,cy-46);
    els.forEach(function(el){
      var a=+el.dataset.a, rad=a*Math.PI/180;
      var px=cx+Math.sin(rad)*rx, py=cy-Math.cos(rad)*ry;
      el.dataset.lit=Math.atan2(px-cx,cy-py)*180/Math.PI;
      /* на узких экранах подпись не должна выходить за край блока */
      var w=el.offsetWidth,h=el.offsetHeight;
      var x0=a<-22?px-w:(a>22?px:px-w/2);
      x0=Math.max(6,Math.min(W-w-6,x0));
      el.style.transform='none'; el.style.left=x0+'px'; el.style.top=(py-h/2)+'px';
    });
  }
  place(); window.addEventListener('resize',place);
  /* При загрузке блок может иметь нулевой размер (скрыт до прокрутки или ещё не построен),
     и подписи уезжали за край. Пересчитываем, как только у блока появляется размер. */
  if(window.ResizeObserver) new ResizeObserver(place).observe(sea);
  if(!REDUCE&&beam){
    var t0=performance.now();
    (function tick(now){
      var ang=SPAN*Math.sin((now-t0)/3200);
      beam.setAttribute('transform','rotate('+ang+' 600 315)');
      els.forEach(function(el){ el.classList.toggle('lit',Math.abs(ang-(+(el.dataset.lit||el.dataset.a)))<13); });
      requestAnimationFrame(tick);
    })(performance.now());
  } else els.forEach(function(el){ el.classList.add('lit'); });
}

