function pkKeys(){
  var br=pkPath[0]||'q1';
  return pkPath.length?['q1'].concat(br==='buy'?['buy2','buy3']:['bld2','bld3']):['q1'];
}
function drawPicker(){
  pkHost=document.getElementById('picker'); if(!pkHost) return;
  var step=pkPath.length, keys=pkKeys();
  var bars='<div class="pk-prog">'+[0,1,2].map(function(k){ return '<i class="'+(k<step?'on':'')+'"></i>'; }).join('')+'</div>';
  if(step<3){
    var key=keys[step]||'q1', q=QUIZ[key];
    pkHost.innerHTML=bars+'<div class="pk-step"><div class="pk-q">'+esc(q.q)+'</div><div class="pk-opts">'+
      q.a.map(function(o,i){ return '<button class="pk-opt" type="button" data-v="'+o.v+'">'+esc(o.t)+'</button>'; }).join('')+'</div>'+
      (step?'<button class="pk-back" type="button" data-pk="back">← Назад</button>':'')+'</div>';
  } else {
    var k=pkPath.join('|'), r=RES[k]||RES['buy|look|link'];
    var s=SVC[r.s], x=r.x?SVC[r.x]:null;
    pkHost.innerHTML=bars+'<div class="pk-step"><div class="pk-res">'+
      '<div class="rk">Что Вам подходит</div><div class="rn">'+esc(s.n)+'</div>'+
      '<div class="rp">'+esc(s.p)+(s.t?' · '+esc(s.t):'')+'</div><p>'+esc(r.d)+'</p>'+
      (x?'<div class="pk-also">Дополнительно имеет смысл: <b>'+esc(x.n)+'</b> — '+esc(x.p)+'</div>':'')+
      '</div><div class="pk-acts">'+
      '<button class="btn b-amber" type="button" data-form="svc" data-svc="'+r.s+'">Оформить заявку'+ARR+'</button>'+
      (x?'<button class="btn b2" type="button" data-form="svc" data-svc="'+r.x+'">'+esc(x.n)+ARR+'</button>':'')+
      '</div><button class="pk-back" type="button" data-pk="again">Пройти заново</button></div>';
  }
}
document.addEventListener('click',function(e){
  var o=e.target.closest('.pk-opt');
  if(o&&o.closest('#picker')){ pkPath.push(o.dataset.v); drawPicker(); return; }
  var b=e.target.closest('[data-pk]');
  if(b){ if(b.dataset.pk==='back') pkPath.pop(); else pkPath=[]; drawPicker(); }
});

