function initBlog(){
  var bp=document.getElementById('blogPosts'), bf=document.getElementById('blogFilter');
  if(!bp||!bf) return;
  if(bf.children.length){
    bf.addEventListener('click',function(e){
      var b=e.target.closest('.bf'); if(!b) return;
      bf.querySelectorAll('.bf').forEach(function(x){ x.classList.toggle('on',x===b); });
      bp.querySelectorAll('.post').forEach(function(p){ p.hidden=!(b.dataset.c==='Все материалы'||p.dataset.c===b.dataset.c); });
    });
    return;
  }
  var cats=['Все материалы'].concat(Object.keys(COVERS));
  bf.innerHTML=cats.map(function(c,i){ return '<button class="bf'+(i?'':' on')+'" type="button" data-c="'+esc(c)+'">'+esc(c)+'</button>'; }).join('');
  function draw(c){
    bp.innerHTML=POSTS.filter(function(p){ return c==='Все материалы'||p.c===c; }).map(function(p){
      return '<article class="post rv in"><div class="post-cover" style="background:'+COVERS[p.c]+'"></div>'+
        '<div class="post-body"><span class="post-cat">'+esc(p.c)+'</span><h4>'+esc(p.t)+'</h4>'+
        '<div class="post-meta"><span>'+p.d+'</span><span>'+p.r+'</span></div></div></article>';
    }).join('');
  }
  draw('Все материалы');
  bf.addEventListener('click',function(e){
    var b=e.target.closest('.bf'); if(!b) return;
    bf.querySelectorAll('.bf').forEach(function(x){ x.classList.toggle('on',x===b); });
    draw(b.dataset.c);
  });
}

