var svState={};
function plural(n,one,few,many){ var a=n%10,b=n%100; return (a===1&&b!==11)?one:(a>=2&&a<=4&&(b<12||b>14))?few:many; }
function svList(){ return SV||SURVEY; }
function surveyHtml(){
  var L=svList(), must=L.filter(function(q){ return q.must; }).length;
  return '<div class="survey" id="svBox"><button class="survey-h" type="button" id="svToggle">'+
    (SV?'<span class="l1">Вопросы о сделке</span>'+
        '<span class="l2">'+L.length+' '+plural(L.length,'вопрос','вопроса','вопросов')+(must?', из них '+must+' '+plural(must,'важный','важных','важных'):'')+'. Можно пропустить любой или ответить «Не знаю»</span>'
       :'<span class="l1">−20% рисков + 20% точности отчёта</span>'+
        '<span class="l2">Ответьте на вопросы ниже<i>·</i>'+L.length+' вопросов. Можно пропустить любой</span>')+
    '<span class="chev"><svg width="11" height="7" viewBox="0 0 11 7" aria-hidden="true"><path d="M1 1l4.5 4.5L10 1" stroke="#C87F17" stroke-width="1.7" fill="none" stroke-linecap="round"/></svg></span>'+
    '</button><div class="survey-b"><div><div class="survey-in"><div class="qtrack" id="svTrack"></div>'+
    '<div class="qbar"><i id="svBar" style="width:0%"></i></div></div></div></div></div>';
}
function svDraw(i,dir){
  var tr=document.getElementById('svTrack'); if(!tr) return;
  var bar=document.getElementById('svBar');
  var SURVEY=svList();
  if(i>=SURVEY.length){
    tr.innerHTML='<div class="qcard in-a"><div class="qdone"><b>Спасибо, этого достаточно</b>'+
      '<span class="small" style="color:#1D5C42">Ответы уйдут вместе с заявкой — проверим внимательнее там, где Вы отметили риск.</span></div>'+
      '<div class="qnav"><button class="qback" type="button" data-sv="back">← К последнему вопросу</button></div></div>';
    if(bar) bar.style.width='100%';
    return;
  }
  var q=SURVEY[i], cur=svState[q.n];
  tr.innerHTML='<div class="qcard in-a"><div class="qmeta"><span class="qnum">Вопрос '+(i+1)+' из '+SURVEY.length+(q.must?' · важный':'')+'</span>'+
    '<button class="qskip" type="button" data-sv="skip">Пропустить →</button></div>'+
    '<div class="qq">'+esc(q.q)+'</div>'+(q.h?'<div class="qh">'+esc(q.h)+'</div>':'')+
    '<div class="qopts">'+q.a.map(function(a){ return '<button class="qopt'+(cur===a?' on':'')+'" type="button" data-a="'+esc(a)+'">'+esc(a)+'</button>'; }).join('')+'</div>'+
    (q.own?'<div class="qown"><input type="text" placeholder="'+esc(q.own)+'" data-svown value="'+esc(svState[q.n+'_own']||'')+'"></div>':'')+
    '<div class="qnav"><button class="qback" type="button" data-sv="back"'+(i?'':' disabled')+'>← Назад</button>'+
    '<span class="qprog">Отвечено: '+Object.keys(svState).filter(function(k){ return k.indexOf('_own')<0; }).length+' из '+SURVEY.length+'</span></div></div>';
  tr.dataset.i=i;
  if(bar) bar.style.width=Math.round(i*100/SURVEY.length)+'%';
}
document.addEventListener('click',function(e){
  var t=e.target.closest('#svToggle');
  if(t){ var b=document.getElementById('svBox'); b.classList.toggle('open');
    if(b.classList.contains('open')&&!document.getElementById('svTrack').childNodes.length) svDraw(0); return; }
  var tr=document.getElementById('svTrack'); if(!tr) return;
  var i=+(tr.dataset.i||0), SURVEY=svList();
  var o=e.target.closest('.qopt');
  if(o&&tr.contains(o)){ svState[SURVEY[i].n]=o.dataset.a; svDraw(i+1); return; }
  var n=e.target.closest('[data-sv]');
  if(n&&tr.contains(n)){
    if(n.dataset.sv==='skip') svDraw(i+1);
    else svDraw(Math.max(0,(tr.querySelector('.qdone')?SURVEY.length:i)-1));
  }
});

/* ============ МОДАЛКИ ============ */
var lastFocus=null;
function openModal(el){
  lastFocus=document.activeElement;
  document.querySelectorAll('.modal').forEach(function(m){ m.classList.remove('on'); m.setAttribute('aria-hidden','true'); });
  el.classList.add('on'); el.setAttribute('aria-hidden','false');
  document.body.classList.add('mopen');
}
function closeModal(){
  document.body.classList.remove('mopen');
  document.querySelectorAll('.modal').forEach(function(m){ m.classList.remove('on'); m.setAttribute('aria-hidden','true'); });
  if(lastFocus&&lastFocus.focus) lastFocus.focus();
}
function docModalEl(){
  var m=document.getElementById('docModal'); if(m) return m;
  /* На страницах правовых документов своего окна нет — создаём такое же, как на остальных страницах */
  m=document.createElement('div'); m.className='modal wide'; m.id='docModal'; m.setAttribute('aria-hidden','true');
  m.innerHTML='<div class="modal-in" role="dialog" aria-modal="true" aria-labelledby="dmT">'+
    '<button class="modal-x" data-close type="button" aria-label="Закрыть"><svg width="13" height="13" viewBox="0 0 13 13"><path d="M1 1l11 11M12 1L1 12" stroke="#0D3B54" stroke-width="1.6" stroke-linecap="round"/></svg></button>'+
    '<h3 id="dmT"></h3><div class="mbody" id="dmB"></div></div>';
  document.body.appendChild(m); return m;
}
