  document.getElementById('fmStep2').hidden = (n!==2);
  if(c&&!c.hidden){
    c.children[0].className = 'go'+(n===1?' on':'');
    c.children[1].className = 'go'+(n===2?' on':'');
    c.children[2].className = '';
  }
  var bk=document.getElementById('fmBack'); if(bk) bk.hidden = (n!==2);
  var b=document.querySelector('#formModal .modal-in'); if(b) b.scrollTop=0;
