function apiDD(path,body){
  return fetch(ESTATE_API+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
  .then(function(res){
    return res.text().then(function(text){
      var d=null; try{ d=text?JSON.parse(text):{}; }catch(x){ d={}; }
      if(!res.ok||d['ок']===false){
        var errs=d['ошибки']; var msg=(errs&&errs.length)?errs.join('; '):('Сервис ответил ошибкой '+res.status);
        var er=new Error(msg); er.status=res.status; er.data=d; throw er;
      }
      return d;
    });
  });
}
function ddLoadForm(types){
  var k=types.join('+');
  if(ddForms[k]) return Promise.resolve(ddForms[k]);
  return apiDD('/api/dd/form',{'тип_объекта':types}).then(function(d){
    var qs=(d['вопросы']||d['анкета']||(Array.isArray(d)?d:[])).map(function(q){
      return { n:q['признак'], q:q['вопрос'], h:q['зачем']||'', must:q['вес']==='обязательный',
               a:(q['ответы']||[]).map(function(o){ return o['текст']; }),
               v:(q['ответы']||[]).map(function(o){ return Object.prototype.hasOwnProperty.call(o,'значение')?{has:true,val:o['значение']}:{has:false}; }) };
    });
    ddForms[k]={ver:d['версия_анкеты'], qs:qs};
    return ddForms[k];
  });
}
