function ddCheckFiles(files){
  if(files.length>DD_MAX_FILES) throw new Error('Можно приложить не больше '+DD_MAX_FILES+' документов');
  files.forEach(function(file){
    var ext=(file.name.split('.').pop()||'').toLowerCase();
    if(DD_EXT.indexOf(ext)<0) throw new Error('Файл «'+file.name+'»: такой формат не принимаем. Подойдут '+DD_EXT.join(', '));
    if(file.size>DD_MAX_FILE) throw new Error('Файл «'+file.name+'» больше 25 МБ');
    if(!file.size) throw new Error('Файл «'+file.name+'» пустой');
  });
}
